              "text": "[6] В стихотворении стихотворение Е. А. Евтушенко «Бабий Яр» Е. А. Евтушенко пишет о необходимости сохранения памяти о жертвах нацизма, об опасности национальной ненависти и о нравственной ответственности общества перед историей."
