              "text": "Они видели не только парады Победы, но и матерей, которые так и не дождались сыновей. Видели фронтовиков, молчавших о пережитом. Видели пустые места за семейными столами. Поэтому война воспринималась не как завершённое историческое событие, а как продолжающаяся человеческая боль."
