              "text": "Многие читатели восприняли публикацию как важный шаг к восстановлению исторической справедливости. Особенно сильное впечатление стихотворение произвело на представителей еврейской интеллигенции и людей, непосредственно связанных с памятью о трагедии Бабьего Яра.[5]"
