              "text": "Одним из них стал композитор Дмитрий Дмитриевич Д. Д. Шостакович. Именно под впечатлением от текста Е. А. Евтушенко он создал свою знаменитую Тринадцатая симфония, первая часть которой основана на стихотворении стихотворение Е. А. Евтушенко «Бабий Яр».[7]"
