              "text": "Его переписывали от руки, читали на неофициальных встречах, обсуждали в студенческих аудиториях и творческих объединениях. Для многих людей знакомство с историей Бабьего Яра началось именно через стихотворение, а не через учебники или исторические исследования.[12]"
