          "title": "Вопросы для письменного размышления",
          "lead": "**1. Может ли поэт иметь нравственное право говорить о том, о чём предпочитает молчать государство, если это вызывает общественный конфликт? Где проходит граница между гражданской ответственностью и политическим протестом?**",
