          "lead": "Военная литература в советской культуре не была единым явлением. Существовали разные способы говорить о войне, памяти и победе. Официальный канон формировал определённый взгляд на события, тогда как поэзия Е. А. Евтушенко расширяла границы допустимого разговора, вводя темы, которые долгое время оставались вне публичного поля. Ниже представлено сопоставление двух подходов.",
