              "text": "После этого раздела остаётся не набор фактов, а ощущение тревожной ясности. Война перестаёт быть только историческим событием и становится пространством человеческих судеб, в котором каждое имя имеет вес и каждое молчание имеет цену. Поэзия Е. А. Евтушенко оставляет чувство, что память о войне никогда не является нейтральной - она всегда требует выбора, всегда предполагает ответственность за то, что именно будет сказано и что будет скрыто."
