              "text": "Остаётся образ голосов, которые долго не звучали: штрафники, о которых не принято было говорить, вдовы, чья жизнь продолжалась в одиночестве, мальчики, не успевшие стать взрослыми, и безымянные жертвы Бабьего Яра. Эти образы складываются не в панораму победы, а в картину цены, которую заплатила страна. В этом мире нет простой завершённости, потому что прошлое не закрывается официальной формулой."
