              "type": "p",
              "text": "Е. А. Евтушенко занимает особое место в военной литературе XX века, потому что он выводит разговор о войне за пределы личного переживания и героического нарратива. В его поэзии война становится не только трагедией народа, но и пространством гражданского выбора, где слово приобретает политическую и моральную силу. Он говорит о том, о чём официальная традиция предпочитала молчать, и именно это молчание превращает его тексты в акт вмешательства в историческую память."
