              "type": "p",
              "text": "Его голос отличается от других авторов тем, что он постоянно обращён к обществу как к ответственному субъекту. Если одни тексты фиксируют боль, а другие воспевают подвиг, то Е. А. Евтушенко задаёт вопрос о том, кто остался за пределами этих формул. Благодаря этому его военная лирика становится не дополнением к общей картине, а отдельной линией внутри литературы о войне - линией ответственности за память."
