          "lead": "Официальные биографии обычно рассказывают о датах, книгах, премиях и выступлениях. Однако за этими фактами остаются моменты, которые помогают увидеть живого человека. Для понимания военной лирики Е. А. Евтушенко особенно важны именно такие эпизоды. Многие его произведения рождались не в кабинете и не за письменным столом, а из личного потрясения, из увиденного собственными глазами, из встреч с людьми и столкновения с памятью, которую общество предпочитало обходить стороной.",
